/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/8.14.2/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    // Build a standalone native executable with GraalVM Native Image (`./gradlew nativeCompile`).
    alias(libs.plugins.graalvm.native)
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // Retained from the existing build; currently unused by application source.
    implementation(libs.guava)
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(25)
    }
}

application {
    // Define the main class for the application.
    mainClass = "mmd2html.Converter"
}

tasks.named<Jar>("jar") {
    archiveBaseName = "mmd2html"
    manifest {
        attributes(
            "Main-Class" to "mmd2html.Converter"
        )
    }
}

graalvmNative {
    binaries {
        named("main") {
            imageName = "mmd2html"
            mainClass = "mmd2html.Converter"
        }
    }
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
    // Test data files are read at run time; a change in them must rerun the tests.
    inputs.dir("test/mmd2html/testcases")
}

// Keep application sources and tests in separate top-level directories.
sourceSets {
    main {
        java.setSrcDirs(listOf("src"))
        resources.setSrcDirs(emptyList<String>())
    }
    test {
        java.setSrcDirs(listOf("test"))
        resources.setSrcDirs(emptyList<String>())
    }
}
